#include <vector>
#include <unordered_map>

class Solution {
public:
    int firstUniqueEven(std::vector<int>& nums) {
        std::unordered_map<int, int> counts;
        for (int x : nums) {
            if (x % 2 == 0) counts[x]++;
        }
        for (int x : nums) {
            if (x % 2 == 0 && counts[x] == 1) return x;
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int firstUniqueEven(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : nums) {
            if (x % 2 == 0) counts.put(x, counts.getOrDefault(x, 0) + 1);
        }
        for (int x : nums) {
            if (x % 2 == 0 && counts.get(x) == 1) return x;
        }
        return -1;
    }
}

